import numpy as np, pandas as pd
from scipy.optimize import least_squares
w=pd.read_csv('/task/output/well_data_tmp.tsv',sep='\t')
l=pd.read_csv('/task/input/plate_layout.tsv',sep='\t')
df=l.merge(w,on='well',how='left')
compounds=sorted(df.loc[df.role=='compound','compound'].unique())
readouts=['marker_per_cell','n_cells']

def fit_one(c, resp, active_mask):
    x=np.asarray(c,float); y=np.asarray(resp,float)
    if len(x)<3:
        return dict(status='few', c50=np.nan, bottom=np.nan, ec50=np.nan, h=np.nan)
    x=np.maximum(x,1e-12)
    # parameters: bottom transformed logistic? direct with bounds
    def resid(p):
        bottom, logec50, logh=p
        ec50=np.exp(logec50); h=np.exp(logh)
        pred=bottom+(1-bottom)/(1+(x/ec50)**h)
        return pred-y
    p0=[0.5,np.log(np.median(x)),0.0]
    bounds=([0.0,np.log(1e-6),np.log(0.05)],[0.999,np.log(1e6),np.log(20)])
    try:
        res=least_squares(resid,p0,bounds=bounds,max_nfev=20000)
        bottom,logec50,logh=res.x; ec50=np.exp(logec50); h=np.exp(logh)
        if bottom<0.5:
            x50=0.5/(0.5-bottom)
            c50=ec50*x50**(1/h)
        else:
            c50=np.inf
        return dict(status='ok', c50=c50, bottom=bottom, ec50=ec50, h=h, cost=res.cost)
    except Exception as e:
        return dict(status='err:'+str(e), c50=np.nan, bottom=np.nan, ec50=np.nan, h=np.nan)

for norm in ['global','row_interp']:
    print('\n===== NORMALIZATION:',norm,'=====')
    for readout in readouts:
        # baseline function
        if norm=='global':
            base=df[(df.role=='vehicle')&(df.qc_pass==1)][readout].mean()
            df['resp']=df[readout]/base
        else:
            df['resp']=np.nan
            for row in 'ABCDEFGH':
                sub=df[df.well.str.startswith(row)]
                vh=sub[(sub.role=='vehicle')&(sub.qc_pass==1)]
                cols=vh['well'].str[1:].astype(int).values
                vals=vh[readout].values
                if len(cols)>=2:
                    coef=np.polyfit(cols,vals,1)
                    pred=np.polyval(coef,sub['well'].str[1:].astype(int).values)
                    pred=np.maximum(pred,1e-12)
                    df.loc[sub.index,'resp']=sub[readout].values/pred
                else:
                    df.loc[sub.index,'resp']=sub[readout].values/vals.mean()
        print('---',readout,'---')
        for comp in compounds:
            sub=df[(df.compound==comp)&(df.role=='compound')&(df.qc_pass==1)].sort_values('dose_uM')
            fit=fit_one(sub.dose_uM.values,sub.resp.values,None)
            if fit['status']!='ok' or not np.isfinite(fit['c50']) or fit['c50']>30:
                call='inactive'
            else:
                call=f"{fit['c50']:.5g}"
            print(f"{comp:9s} c50={call:10s} bottom={fit['bottom']:.3f} ec50={fit['ec50']:.4g} h={fit['h']:.3f} n={len(sub)}")
