rows=sorted(veh.row.unique())

def design(df,kind):
    cols=df.col.values.astype(float); c=cols-6.5
    rowd=np.column_stack([(df.row.values==r).astype(float) for r in rows[:-1]]) if len(rows)>1 else np.zeros((len(df),0))
    if kind=='global': return np.ones((len(df),1))
    if kind=='rowmean': return np.column_stack([np.ones(len(df)),rowd])
    if kind=='row_lin': return np.column_stack([np.ones(len(df)),c,rowd])
    if kind=='row_quad': return np.column_stack([np.ones(len(df)),c,c*c,rowd])
    if kind=='row_cubic': return np.column_stack([np.ones(len(df)),c,c*c,c**3,rowd])
    if kind=='row_colfe':
        cold=np.column_stack([(df.col.values==cc).astype(float) for cc in sorted(df.col.unique())[1:]])
        return np.column_stack([np.ones(len(df)),cold,rowd])

for readout in ['marker_per_cell','n_cells']:
 print('\n====',readout,'====')
 y=np.log(veh[readout].values.astype(float))
 for kind in ['global','rowmean','row_lin','row_quad','row_cubic','row_colfe']:
  X=design(veh,kind)
  beta=np.linalg.lstsq(X,y,rcond=None)[0]
  train=np.sqrt(np.mean((y-X@beta)**2))
  loo=[]
