   tr=np.ones(len(y),bool); tr[i]=False
   b=np.linalg.lstsq(X[tr],y[tr],rcond=None)[0]
   loo.append(y[i]-X[i]@b)
  loo=np.array(loo)
  print(f'{kind:9s} p={X.shape[1]:2d} train={train:.4f} loo={np.sqrt(np.mean(loo**2)):.4f}')
