import numpy as np, pandas as pd
from scipy.optimize import least_squares
w=pd.read_csv('/task/output/well_data_tmp.tsv',sep='\t')
l=pd.read_csv('/task/input/plate_layout.tsv',sep='\t')
df=l.merge(w,on='well',how='left')
veh=df[(df.role=='vehicle')&(df.qc_pass==1)].copy()
veh['row']=veh.well.str[0]; veh['col']=veh.well.str[1:].astype(int)
rows=sorted(veh.row.unique()); allcols=sorted(veh.col.unique())

def design(df,kind):
    c=df.col.values.astype(float)-6.5
    rowd=np.column_stack([(df.row.values==r).astype(float) for r in rows[1:]])
    if kind=='row_lin':
        return np.column_stack([np.ones(len(df)),c,rowd])
    if kind=='row_quad':
        return np.column_stack([np.ones(len(df)),c,c*c,rowd])
    if kind=='row_colfe':
        cold=np.column_stack([(df.col.values==cc).astype(float) for cc in allcols[1:]])
        return np.column_stack([np.ones(len(df)),cold,rowd])

def get_baseline(kind,readout):
    y=np.log(veh[readout].values.astype(float))
    X=design(veh,kind)
    beta=np.linalg.lstsq(X,y,rcond=None)[0]
    def pred(row,col):
        d=pd.DataFrame({'row':[row],'col':[col]})
        return float(np.exp(design(d,kind)@beta)[0])
    return pred

def fit_curve(c,y):
    x=np.asarray(c,float); y=np.asarray(y,float); x=np.maximum(x,1e-12)
    def resid(p):
        b,le,lh=p; e=np.exp(le); h=np.exp(lh)
        return b+(1-b)/(1+(x/e)**h)-y
    res=least_squares(resid,[0.5,np.log(np.median(x)),np.log(1.0)],bounds=([0,np.log(1e-6),np.log(0.3)],[0.98,np.log(1e6),np.log(10)]),max_nfev=100000)
    b,le,lh=res.x; e=np.exp(le); h=np.exp(lh)
    if b>=0.5:
        c50=np.inf
    else:
        c50=e*(0.5/(0.5-b))**(1/h)
    r=np.sqrt(np.mean(resid(res.x)**2))
    return b,e,h,c50,r

compounds=sorted(df[df.role=='compound'].compound.unique())
for kind in ['row_lin','row_quad','row_colfe']:
    print('\n########',kind,'########')
    for readout in ['marker_per_cell','n_cells']:
        pred=get_baseline(kind,readout)
        df['resp']=[df.loc[i,readout]/pred(r[0],int(r[1:])) for i,r in df.well.items()]
        print('\n--',readout,'--')
        for comp in compounds:
            sub=df[(df.compound==comp)&(df.role=='compound')&(df.qc_pass==1)].sort_values('dose_uM')
            maxd=sub.dose_uM.max()
            b,e,h,c50,r=fit_curve(sub.dose_uM.values,sub.resp.values)
            call=f'{c50:.6g}' if (b<0.5 and np.isfinite(c50) and c50<=maxd) else 'inactive'
            print(f'{comp:9s} c50={call:10s} bottom={b:.3f} EC50={e:.4g} h={h:.3f} rmse={r:.3f}')
